import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>GIF, WebP и MP4 — три способа показать движение в интернете. Они выглядят похоже, но весят и работают совершенно по-разному.</p>\n<p>GIF играет везде без нажатия кнопки. WebP весит меньше и выглядит чище. MP4 весит в разы меньше обоих, но требует плеера.</p>\n<p>Это сравнение покажет, что даёт каждый формат, где каждый выигрывает и как выбрать правильно.</p>\n<h2 id=\"short-answer\">Короткий ответ</h2>\n<p>Для чатов и реакций берите GIF: он играет везде, зацикливается сам и не требует ничего, кроме отправки.</p>\n<p>Для сайта берите WebP: он весит меньше GIF, выглядит чище и играет так же автоматически.</p>\n<p>Для длинных роликов берите MP4: он весит в разы меньше GIF и WebP, а разница в качестве огромна.</p>\n<p>Когда сомневаетесь, начните с GIF для чатов и WebP для сайта. MP4 оставьте для видео длиннее нескольких секунд.</p>\n<h2 id=\"gif-format\">Формат GIF</h2>\n<p>GIF появился в 1987 году и до сих пор живёт. Он хранит до 256 цветов на кадр и поддерживает простую прозрачность.</p>\n<p>Главное преимущество GIF — совместимость: он играет везде, в чатах, письмах и на страницах, без плеера и без нажатия кнопки.</p>\n<p>Главный недостаток — вес. Десятисекундный ролик может весить 20 МБ, потому что каждый кадр хранится почти полностью.</p>\n<p>GIF зацикливается сам: анимация повторяется без управления. Для коротких реакций это идеально.</p>\n<h2 id=\"webp-format\">Формат WebP</h2>\n<p>WebP — современный формат от Google. Он поддерживает анимацию, прозрачность и сжимает намного лучше GIF.</p>\n<p>Анимированный WebP при том же качестве весит заметно меньше GIF. Края чище, градиенты глаже, а цвета точнее.</p>\n<p>WebP тоже играет автоматически, как GIF, и зацикливается сам. Для сайта это прямая замена GIF с меньшим весом.</p>\n<p>Подвох — в совместимости: старые системы и некоторые платформы не принимают WebP. Проверьте место назначения, прежде чем выбирать его.</p>\n<h2 id=\"mp4-format\">Формат MP4</h2>\n<p>MP4 — это видеоформат, а не формат изображений. Он сжимает движение между кадрами, а не каждый кадр отдельно, поэтому весит в разы меньше.</p>\n<p>Десятисекундная анимация может весить 15 МБ как GIF и 1,5 МБ как MP4. Разница в десять раз — это не опечатка.</p>\n<p>MP4 поддерживает звук, высокое разрешение и миллионы цветов. Для длинных роликов ему нет равных.</p>\n<p>Недостаток — в воспроизведении: MP4 требует плеера и часто нажатия для запуска. Он не зацикливается сам так просто, как GIF.</p>\n<h2 id=\"file-size-compared\">Сравнение веса файлов</h2>\n<p>Возьмите десятисекундный ролик: как GIF он весит около 15–20 МБ, как WebP — заметно меньше, а как MP4 — около 1,5 МБ.</p>\n<p>Разница между GIF и MP4 — в десять раз. Для страницы с несколькими анимациями это решает, будет ли страница быстрой или медленной.</p>\n<p>WebP находится посередине: легче GIF, но тяжелее MP4. Для коротких циклов разница с GIF уже заметна, а для длинных — огромна.</p>\n<p>Для чатов вес решает, отправится ли файл: лимиты 8–10 МБ отсекают большие GIF, а MP4 того же ролика проходит легко.</p>\n<p>Считайте общий вес страницы, а не отдельных файлов. Три GIF по 10 МБ — это 30 МБ, а три MP4 — всего 4,5 МБ.</p>\n<h2 id=\"quality-compared\">Сравнение качества</h2>\n<p>При одинаковом весе WebP выглядит чище GIF: края резче, градиенты глаже, а цвета точнее. Ограничение в 256 цветов у GIF даёт о себе знать.</p>\n<p>MP4 при любом весе выглядит лучше обоих: миллионы цветов, плавные градиенты и резкие края. Видеоформат создан для движения.</p>\n<p>GIF страдает от палитры: фотографические анимации показывают полосы и пятна, которых нет в WebP и MP4.</p>\n<p>Для плоской графики разница меньше: простые цвета и резкие края GIF передаёт хорошо, и преимущество WebP невелико.</p>\n<p>Проверяйте качество на реальном экране, где анимация будет показываться. Миниатюры скрывают различия, которые видны в полном размере.</p>\n<h2 id=\"compatibility-compared\">Сравнение совместимости</h2>\n<p>GIF поддерживают все: браузеры, чаты, почта, соцсети. Это единственный формат, который играет везде без исключений.</p>\n<p>WebP поддерживают все современные браузеры, но не все платформы и старые системы. Проверьте место назначения перед выбором.</p>\n<p>MP4 поддерживают все браузеры через элемент video, но для воспроизведения нужен плеер и часто нажатие кнопки.</p>\n<p>Для писем GIF — единственный надёжный выбор: видео в письмах почти не работает, а WebP поддерживают не все почтовые клиенты.</p>\n<p>Когда совместимость важнее всего, берите GIF. Когда вес важнее, берите WebP или MP4.</p>\n<h2 id=\"when-to-use-each\">Когда использовать каждый формат</h2>\n<p>GIF: короткие реакции в чатах, стикеры, анимации в письмах. Везде, где важна мгновенная игра без нажатий.</p>\n<p>WebP: анимации на сайте, короткие циклы в блоге, баннеры. Везде, где нужен автоматический запуск и меньший вес, чем у GIF.</p>\n<p>MP4: длинные ролики, записи экрана, видеоинструкции. Везде, где анимация длится дольше нескольких секунд.</p>\n<p>Если анимация короче трёх секунд и нужна в чате — GIF. Если она на сайте и должна быть лёгкой — WebP. Если дольше десяти секунд — MP4.</p>\n<p>Держите под рукой конвертер: один и тот же ролик можно подготовить во всех трёх форматах под разные места.</p>\n<h2 id=\"converting-between\">Конвертация между форматами</h2>\n<p>GIF в WebP: вес падает заметно, качество растёт, а анимация продолжает играть автоматически. Это лучшая конвертация для сайта.</p>\n<p>GIF в MP4: вес падает в разы, качество растёт, но теряется автоматический запуск. Для длинных роликов это стоит того.</p>\n<p>MP4 в GIF: вес вырастает в разы, качество падает, но появляется автоматический запуск. Делайте это только для чатов, где нужен GIF.</p>\n<p>WebP в GIF: обратная конвертация для совместимости. Вес вырастет, но файл начнёт играть везде.</p>\n<p>Конвертируйте из оригинала, а не из сжатой копии. Каждая конвертация с потерями добавляет повреждения.</p>\n<h2 id=\"web-performance\">Производительность сайта</h2>\n<p>GIF на веб-странице — самый тяжёлый элемент, который она может нести. Один GIF на 10 МБ перевешивает все остальные изображения вместе.</p>\n<p>WebP решает часть проблемы: тот же цикл весит меньше и грузится быстрее. Страница с WebP вместо GIF заметно быстрее.</p>\n<p>MP4 решает проблему полностью: видео в десять раз легче GIF и не блокирует загрузку страницы.</p>\n<p>Ограничьте число анимаций на странице. Три зацикленные анимации соревнуются за внимание, а одна сфокусированная работает лучше.</p>\n<p>Используйте ленивую загрузку для анимаций ниже сгиба. Они не видны при открытии страницы, поэтому браузер может загрузить их позже.</p>\n<h2 id=\"accessibility-animated\">Доступность анимаций</h2>\n<p>Мигающие анимации могут вызывать дискомфорт и даже приступы у людей с фоточувствительностью. Избегайте быстрого мигания во всех форматах.</p>\n<p>Добавляйте alt-текст, описывающий анимацию. Пользователи программ чтения с экрана не видят движение, им нужно описание.</p>\n<p>Дайте пользователям способ остановить анимацию, когда это возможно. Зацикленная анимация без паузы раздражает.</p>\n<p>Не полагайтесь только на анимацию для передачи информации. Важное сообщение должно быть и в тексте рядом.</p>\n<p>Уважайте настройки пользователя: многие браузеры позволяют отключить анимацию, и ваш сайт должен работать и без неё.</p>\n<h2 id=\"choosing-summary\">Итог выбора</h2>\n<p>Чаты и реакции: GIF. Он играет везде, зацикливается сам и не требует ничего.</p>\n<p>Сайт и блог: WebP. Он легче GIF, выглядит чище и играет так же автоматически.</p>\n<p>Длинные ролики: MP4. Он весит в разы меньше и даёт лучшее качество.</p>\n<p>Письма: GIF. Видео в письмах почти не работает, а WebP поддерживают не все клиенты.</p>\n<p>Когда сомневаетесь, сделайте все три версии и проверьте каждую в её месте назначения.</p>\n<h2 id=\"bandwidth-costs\">Стоимость трафика</h2>\n<p>Трафик стоит денег: и вам, и посетителям. GIF на 20 МБ для тысячи посетителей — это 20 ГБ трафика.</p>\n<p>Тот же ролик как MP4 на 1,5 МБ для тысячи посетителей — это 1,5 ГБ. Разница в тринадцать раз — это реальные деньги на хостинге.</p>\n<p>Мобильные посетители платят за трафик из своего кармана. Тяжёлые GIF раздражают их вдвойне: медленно и дорого.</p>\n<p>WebP находится посередине: дешевле GIF, но дороже MP4. Для коротких циклов это разумный компромисс.</p>\n<p>Считайте трафик при выборе формата. Один GIF дёшев, а тысяча показов — уже нет.</p>\n<h2 id=\"loop-seams\">Швы цикла</h2>\n<p>Зацикленная анимация должна переходить от конца к началу плавно, без резкого скачка. Шов цикла — это видимый разрыв в этом переходе.</p>\n<p>GIF и WebP зацикливаются автоматически, поэтому шов виден сразу. Проверяйте первый и последний кадры: они должны быть похожи.</p>\n<p>MP4 тоже можно зациклить, но для этого нужен плеер с настройкой цикла. Без неё видео остановится в конце.</p>\n<p>Если цикл рвётся, обрежьте анимацию так, чтобы начало и конец совпадали. Плавный цикл выглядит профессионально.</p>\n<p>Тестируйте цикл несколько раз подряд. Один проход скрывает шов, который виден на третьем круге.</p>\n<h2 id=\"sound-animations\">Звук и анимации</h2>\n<p>GIF и WebP звука не поддерживают: это немые форматы. Если нужен звук, берите MP4.</p>\n<p>MP4 поддерживает звук, и это его преимущество для инструкций и роликов. Но звук в автоматическом воспроизведении часто блокируется браузерами.</p>\n<p>Для чатов звук не нужен: реакции передают эмоцию без слов. GIF без звука — это норма.</p>\n<p>Для сайта звук может раздражать: посетители не ждут, что страница заговорит. Используйте звук только по явному запросу.</p>\n<p>Когда звук важен, используйте MP4 с кнопкой включения звука. Автоматический звук — плохой тон.</p>\n<h2 id=\"testing-formats\">Тестирование форматов</h2>\n<p>Сделайте один ролик во всех трёх форматах и сравните их рядом. Смотрите на вес, качество и удобство воспроизведения.</p>\n<p>Проверьте каждый формат в его месте назначения: GIF — в чате, WebP — на сайте, MP4 — в плеере.</p>\n<p>Покажите все три версии другу, не говоря, какая какая. Свежий взгляд замечает то, что вы перестали видеть.</p>\n<p>Измерьте скорость страницы с каждой версией. Цифры убеждают лучше впечатлений.</p>\n<p>Запишите вывод для своего типа анимаций. В следующий раз выбор займёт секунды.</p>\n<h2 id=\"final-verdict-formats\">Итоговый вердикт</h2>\n<p>GIF остаётся королём чатов: совместимость и мгновенный запуск перевешивают вес для коротких реакций.</p>\n<p>WebP — лучший выбор для сайта: легче GIF, чище на вид и играет так же автоматически.</p>\n<p>MP4 — лучший выбор для длинных роликов: вес в разы меньше, качество лучше, а звук — бонус.</p>\n<p>Нет одного победителя для всех случаев. Есть правильный формат для каждого места назначения.</p>\n<p>Выбирайте по назначению, а не по привычке. GIF по привычке для длинного ролика — это десять мегабайт впустую.</p>\n<h2 id=\"keep-testing-formats\">Продолжайте тестировать</h2>\n<p>Форматы меняются: WebP становится повсеместным, а новые форматы уже на подходе. То, что было лучшим вчера, завтра может устареть.</p>\n<p>Тестируйте новые форматы на своих анимациях. Один тест стоит больше десяти статей.</p>\n<p>Следите за лимитами платформ: они меняются, и прошлогодние настройки могут не подойти сегодня.</p>\n<p>Делитесь знаниями с командой. Общая заметка с форматами и лимитами экономит часы каждому.</p>\n<p>И помните: лучший формат — это тот, который передаёт идею, загружается быстро и играет там, где нужно.</p>\n<p>Когда выбираете формат для новой анимации, начните с места назначения: чат, сайт, письмо или презентация. Место решает больше, чем привычка.</p>\n<p>Сделайте один ролик во всех трёх форматах и сравните их рядом. Смотрите на вес, качество и удобство воспроизведения — все три фактора сразу.</p>\n<p>Проверьте каждый формат в его месте назначения: GIF — в чате, WebP — на сайте, MP4 — в плеере. Тест в реальном месте стоит больше теории.</p>\n<p>Покажите все три версии другу, не говоря, какая какая. Свежий взгляд замечает то, что вы перестали видеть.</p>\n<p>Измерьте скорость страницы с каждой версией. Цифры убеждают лучше впечатлений, особенно когда речь идёт о мегабайтах трафика.</p>\n<p>Запишите вывод для своего типа анимаций: какой формат, когда и почему. В следующий раз выбор займёт секунды.</p>\n<p>Следите за поддержкой форматов: WebP становится повсеместным, а новые форматы уже на подходе. То, что было лучшим вчера, завтра может устареть.</p>\n<p>Не забывайте про доступность: мигающие анимации вредны, а alt-текст нужен всем форматам одинаково.</p>\n<p>Для командной работы запишите выбор формата в общую заметку. Когда каждый автор выбирает по-своему, сайт выглядит несогласованно.</p>\n<p>Держите под рукой конвертер: один и тот же ролик можно подготовить во всех трёх форматах под разные места.</p>\n<p>И помните: нет одного победителя для всех случаев. Есть правильный формат для каждого места назначения — и ваша задача его найти.</p>\n<p>Возьмите десятисекундный ролик: как GIF он весит около 15–20 МБ, как WebP — заметно меньше, а как MP4 — около 1,5 МБ. Разница в десять раз — это не опечатка.</p>\n<p>Зацикленная анимация должна переходить от конца к началу плавно, без резкого скачка. Проверьте первый и последний кадры: они должны быть похожи.</p>\n<p>GIF и WebP звука не поддерживают: это немые форматы. Если нужен звук, берите MP4, но помните, что браузеры часто блокируют автоматический звук.</p>\n<p>Трафик стоит денег: GIF на 20 МБ для тысячи посетителей — это 20 ГБ трафика. Тот же ролик как MP4 — всего 1,5 ГБ.</p>\n<p>GIF в WebP конвертируется легко: вес падает заметно, качество растёт, а анимация продолжает играть автоматически.</p>\n<p>MP4 в GIF — обратная конвертация для чатов: вес вырастает в разы, но файл начнёт играть везде без нажатия кнопки.</p>\n<p>Проверьте каждый формат в его месте назначения: GIF — в чате, WebP — на сайте, MP4 — в плеере. Тест в реальном месте стоит больше теории.</p>\n<p>Форматы меняются: WebP становится повсеместным, а новые форматы уже на подходе. То, что было лучшим вчера, завтра может устареть.</p>\n<p>Чек-лист выбора формата: чат — GIF, сайт — WebP, длинный ролик — MP4, письмо — GIF. Четыре правила покрывают почти все задачи.</p>\n<p>Если сомневаетесь, сделайте все три версии и проверьте каждую в её месте назначения. Тест в реальном месте стоит больше теории.</p>\n<p>Для презентаций GIF удобен тем, что играет без плеера: вставьте его в слайд, и он зациклится сам, без нажатий и настроек.</p>\n<p>Если сомневаетесь между форматами, начните с WebP: в большинстве случаев он даёт лучший баланс веса и качества.</p>\n<p>Полное руководство по GIF читайте в статье <a href=\"/ru/blog/kak-szhat-gif-polnoe-rukovodstvo/\">Как сжать GIF: полное руководство</a>. Практические шаги — в статье <a href=\"/ru/blog/kak-szhat-gif/\">Как сжать GIF</a>. Сжать GIF можно в инструменте <a href=\"/ru/szhat-gif/\">сжатия GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Лучше ли WebP, чем GIF, для анимаций?","answer":"Для сайта — да: анимированный WebP весит заметно меньше GIF при том же качестве, а края и градиенты выглядят чище. Для чатов GIF пока надёжнее: его поддерживают все платформы без исключений, а WebP — не все."},{"question":"Можно ли использовать MP4 вместо GIF на сайте?","answer":"Да, и для длинных анимаций это лучший выбор: MP4 весит в разы меньше GIF. Но MP4 требует плеера и часто нажатия для запуска, а GIF играет автоматически. Для коротких циклов GIF или WebP удобнее."},{"question":"Почему люди до сих пор используют GIF, если MP4 намного меньше?","answer":"Потому что GIF играет везде без нажатия кнопки и зацикливается сам. В чатах, письмах и соцсетях это важнее веса. MP4 выигрывает для длинных роликов, но для короткой реакции GIF проще и надёжнее."},{"question":"Поддерживает ли анимированный WebP прозрачность?","answer":"Да. Анимированный WebP поддерживает прозрачность, как и GIF, причём с более плавными краями. Для стикеров и наложений WebP даёт более чистый результат при меньшем весе."},{"question":"Какой длины должна быть анимация в формате GIF?","answer":"Короткой: две-три секунды для реакций и до десяти секунд для демонстраций. Длинные GIF весят очень много, потому что каждый кадр хранится почти полностью. Для роликов дольше десяти секунд используйте MP4."},{"question":"Можно ли конвертировать GIF в MP4 без потери цикла?","answer":"Да, но цикл нужно настроить в плеере: MP4 сам по себе не зацикливается, как GIF. Включите зацикливание в настройках плеера или в HTML-атрибуте loop. Проверьте, что конец ролика плавно переходит в начало."}];
